"""Drive a real agent-stream run against the production bridge and log every event."""

from __future__ import annotations

import json
import sys
import time
import uuid

import httpx

API = "http://127.0.0.1:8686"
URL = sys.argv[1]
ENV_PATH = "$REPO_JOB_HUNTER/.env"

api_key: str | None = None
for line in open(ENV_PATH):
    if line.startswith("CLOUD_API_KEY="):
        api_key = $SECRET"=", 1)[1].strip().strip('"').strip("'")
        break

payload = {
    "request_id": uuid.uuid4().hex,
    "url": URL,
    "executor_backend": "playwright",
    "execution_host": "local",
    "controls": [],
    "profile_data": {},
    "debug_enabled": True,
}
headers = {"X-API-Key": api_key} if api_key else {}
print(
    f"POST {API}/api/agent/stream request_id={payload['request_id']} url={URL}",
    flush=True,
)
with httpx.stream(
    "POST",
    f"{API}/api/agent/stream",
    headers=headers,
    json=payload,
    timeout=httpx.Timeout(900.0, connect=30.0),
) as resp:
    print(f"status={resp.status_code}", flush=True)
    if resp.status_code >= 400:
        print(resp.read().decode()[:2000], flush=True)
        sys.exit(1)
    for line in resp.iter_lines():
        if not line:
            continue
        if line.startswith("data:"):
            raw = line[5:].strip()
            try:
                ev = json.loads(raw)
                stamp = time.strftime("%H:%M:%S")
                summary = {
                    k: v
                    for k, v in ev.items()
                    if k not in ("type", "sequence")
                }
                print(
                    f"[{stamp}] {ev.get('type')} seq={ev.get('sequence')} "
                    f"{json.dumps(summary)[:400]}",
                    flush=True,
                )
            except json.JSONDecodeError:
                print(f"RAW: {raw[:300]}", flush=True)
        elif line.startswith("event:"):
            print(f"EVENT: {line[6:].strip()}", flush=True)
        else:
            print(f"RAW: {line[:200]}", flush=True)

